                        function,
                        &current,
                        &dag_memo::test_key(
                            pointer,
                            pointers.iter().position(|p| *p == pointer).unwrap(),
                            continuation
                        ),
                        ledger
                    )?,
                    if continuation == 3 {
                        None
                    } else {
                        Some(pointers.iter().position(|p| *p == pointer).unwrap())
                    },
