        .movement(
            function,
            &mut build,
            1,
            Label::End(SkeletonTerminal::Success),
            0,
        )
        .unwrap();
    automaton
        .movement(
            function,
            &mut build,
            6,
            Label::End(SkeletonTerminal::Failure),
            0,
