    /// `SOURCE` resolves to this one function.
    const PROGRAM_FUNCTIONS: usize = 1;

    type Outcome = (
        std::thread::Result<()>,
        OracleReceipt,
        Result<(), OracleRefusal>,
    );

    fn run(allowance: usize, work: usize) -> Outcome {
        let program =
