fn receiving_bytes() -> usize {
    use std::mem::size_of;
    2 * size_of::<Result<(), Diagnostic>>()
        + size_of::<&mut SkeletonWork<'_, '_>>()
        + size_of::<&mut Vec<ExprSkeletonPath>>()
        + size_of::<&ResolvedFunction>()
        + size_of::<&mut ReplayBudget>()
        + size_of::<&str>()
        + 3 * size_of::<usize>()
        + size_of::<Option<usize>>()
        + 4 * size_of::<bool>()
