    let share_prefix = work.shares_prefix_tail(&suffixes)?;
    if sequence_vector::can_reuse(sequence_vector::Candidate {
        prefixes: &prefixes,
        suffixes: &suffixes,
        budget: work.budget,
    }) {
        work.budget.reserve_array::<u8>(
            work.function,
            sequence_vector::receiving_bytes(),
            "single-successor receiving frame",
