                            ResolvedExprKind::Call { .. }
                                if crate::vec_ops::string_slot::inspect(value).is_some() =>
                            {
                                Some(origin)
                            }
                            ResolvedExprKind::BorrowPlace { .. }
                            | ResolvedExprKind::VecFieldRead { .. }
                            | ResolvedExprKind::ByteRange { .. } => Some(origin),
                            _ => None,
                        };
