                        ValidationBinding {
                            contract_local,
                            mutable: *mutable,
                            ty: binding.ty.clone(),
                            ownership: binding.ownership,
                            availability: Availability::Available,
                            active_loans: BTreeSet::new(),
                            moved_places: BTreeMap::new(),
                            definitely_partial: BTreeSet::new(),
                        },
