                        expression,
                        statements,
                        tail,
                        index: index + 1,
                        scope,
                        outer,
                        outer_ids,
                        path,
                    })?;
                }
                Frame::BlockAfterAssign {
                    expression,
                    statements,
                    tail,
                    index,
                    scope,
                    outer,
                    outer_ids,
                    path,
                } => {
                    let assigned_scope = scopes.pop().expect("block assign scope retained");
                    let mut scope = scope;
                    let ResolvedStatement::Assign {
                        binding,
                        field,
                        value: assigned,
                        span: assignment_span,
                        ..
                    } = &statements[index]
                    else {
                        unreachable!("assign frame resumes at an assignment statement")
                    };
