                        publication.publish(&scope)?;
                    }
                    frames.push(Frame::RecordNext {
                        expression,
                        fields,
                        expected,
                        record,
                        arguments,
                        seen,
                        index: index + 1,
                        scope,
                        path,
                    })?;
