                        let initializer = &fields[index];
                        let mut seen = seen;
                        if !expected.iter().any(|field| field.id == initializer.field) {
                            return Err(scope_checkpoint::paths::diagnostic(format_args!(
                                "constructor for `{case}` contains foreign field `{}`",
                                initializer.field
                            )));
