                        && !has_direct_bytes
                        && (!declaration.type_parameters.is_empty()
                            || fields.iter().any(|field| {
                                !super::type_reachability::is_admitted_owned_string_variant_field(
                                    &self.program.declarations,
                                    &field.ty,
                                )
                            }))
