                || declaration
                    .type_parameters
                    .iter()
                    .enumerate()
                    .any(|(index, parameter)| usize::try_from(parameter.index) != Ok(index))
                || declaration
                    .type_parameters
                    .iter()
                    .map(|parameter| &parameter.name)
                    .collect::<BTreeSet<_>>()
                    .len()
                    != declaration.type_parameters.len()
